55|  const volumeRef = useRef(0.8);
56|  const fadeRef = useRef<number | null>(null);
57|  const loopArmedRef = useRef<string | null>(null);
58|  const trackRef = useRef<Track | null>(track);
59|  trackRef.current = track;
60|  const fadeSecRef = useRef(fadeSec);
61|  fadeSecRef.current = fadeSec;
62|  const onEndedRef = useRef(onEnded);
63|  onEndedRef.current = onEnded;
64|  const playingRef = useRef(false);
65|  const startedRef = useRef(false);
66|  const firstPlayRef = useRef(true);
67|
68|  // Scheduler fade when set, else the config default; never 0 mid session.
69|  function loopFadeSec() {
70|    return fadeSecRef.current > 0 ? fadeSecRef.current : MUSIC_CONFIG.crossfadeSec;
71|  }
72|  const [started, setStarted] = useState(false);
73|  const [playing, setPlaying] = useState(false);
74|  const [volume, setVolume] = useState(0.8);
75|  const requestPlayRef = useRef((_: Track, __: number) => {});
76|
77|  const [reducedMotion, setReducedMotion] = useState(
78|    () =>
79|      typeof window !== "undefined" &&
80|      !!window.matchMedia?.("(prefers-reduced-motion: reduce)").matches,
81|  );
82|
83|  useEffect(() => {
84|    const query = window.matchMedia?.("(prefers-reduced-motion: reduce)");
85|    if (!query) return;
86|    const onChange = (event: MediaQueryListEvent) => setReducedMotion(event.matches);
87|    query.addEventListener("change", onChange);
88|    return () => query.removeEventListener("change", onChange);
89|  }, []);
90|
91|  function applyLevels() {
92|    const els = [firstRef.current, secondRef.current];
93|    els.forEach((el, i) => {
94|      if (el) el.volume = Math.min(1, Math.max(0, (levelRef.current[i] ?? 0) * volumeRef.current));
95|    });
96|  }
97|
98|  function cancelFade() {
99|    if (fadeRef.current !== null) {
100|      cancelAnimationFrame(fadeRef.current);
101|      fadeRef.current = null;
102|    }
103|  }
104|
105|  // Assigned each render so handlers always see fresh refs. Fades from
106|  // the currently louder element to the newest track; a mid-fade request
107|  // cancels the pending fade and starts from current levels.
108|  requestPlayRef.current = (next: Track, durSec: number) => {
109|    const els = [firstRef.current, secondRef.current];
110|    const srcIdx = (levelRef.current[0] ?? 0) >= (levelRef.current[1] ?? 0) ? 0 : 1;
111|    const dstIdx = 1 - srcIdx;
112|    const srcEl = els[srcIdx];
113|    const dst = els[dstIdx];
114|    if (!srcEl || !dst) return;
115|    cancelFade();
116|    if (trackRef.current?.id !== next.id) loopArmedRef.current = null;
117|    trackRef.current = next;
118|    dst.src = next.src;
119|    dst.onloadedmetadata = () => {
120|      if (next.startSec > 0 && Number.isFinite(dst.duration) && next.startSec < dst.duration) {
121|        try {
122|          dst.currentTime = next.startSec;
123|        } catch {
124|          // Past the end; leave playback at zero.
125|        }
126|      }
127|    };
128|    if (!playingRef.current || durSec <= 0) {
129|      levelRef.current = [0, 0];
130|      levelRef.current[dstIdx] = 1;
131|      audibleRef.current = dstIdx;
132|      srcEl.pause();
133|      applyLevels();
134|      if (playingRef.current) void dst.play().catch(() => undefined);
135|      return;
136|    }
137|    if (playingRef.current) void dst.play().catch(() => undefined);
138|    const startSrc = levelRef.current[srcIdx] ?? 0;
139|    const startDst = levelRef.current[dstIdx] ?? 0;
140|    let t0 = performance.now();
141|    let prev = t0;
142|    const tick = (now: number) => {
143|      // Pause freezes the fade; resume continues from the frozen point.
144|      if (!playingRef.current) {
145|        t0 += now - prev;
146|        prev = now;
147|        fadeRef.current = requestAnimationFrame(tick);
148|        return;
149|      }
150|      prev = now;
151|      const t = Math.min(1, (now - t0) / (durSec * 1000));
152|      levelRef.current[srcIdx] = startSrc * Math.cos((t * Math.PI) / 2);
153|      levelRef.current[dstIdx] = startDst + (1 - startDst) * Math.sin((t * Math.PI) / 2);
154|      applyLevels();
155|      if (t < 1) {
156|        fadeRef.current = requestAnimationFrame(tick);
157|        return;
158|      }
159|      fadeRef.current = null;
160|      levelRef.current[srcIdx] = 0;
161|      levelRef.current[dstIdx] = 1;
162|      audibleRef.current = dstIdx;
163|      applyLevels();
164|      srcEl.pause();
165|    };
166|    fadeRef.current = requestAnimationFrame(tick);
167|  };
168|
169|  const trackId = track?.id ?? null;
170|  useEffect(() => {
171|    const next = trackRef.current;
172|    if (!started || !next) {
173|      // Before the first press, swaps only change src.
174|      if (!started && next) {
175|        const el = [firstRef.current, secondRef.current][audibleRef.current];
176|        if (el && !el.src.endsWith(next.src)) el.src = next.src;
177|      }
178|      return;
179|    }
180|    // The single start path: fade 0 on the very first press. replayNonce
181|    // re-cues the same track (one-track playlist wrap); nothing else is a dep
182|    // so volume, pause/play, and re-renders never restart the track.
183|    const dur = firstPlayRef.current ? 0 : fadeSecRef.current;
184|    firstPlayRef.current = false;
185|    requestPlayRef.current(next, dur);
186|  }, [started, trackId, replayNonce]);
187|
188|  useEffect(() => cancelFade, []);
189|
190|  function handleTimeUpdate(index: number, el: HTMLAudioElement) {
191|    const next = trackRef.current;
192|    // A playlist track always runs to its end so the scheduler advances.
193|    if (!next || !next.loop || playlistOn || index !== audibleRef.current) return;
194|    const fade = loopFadeSec();
195|    const duration = el.duration;
196|    if (!Number.isFinite(duration) || duration <= fade * 2) return;
197|    const remain = duration - el.currentTime;
198|    if (remain <= fade && loopArmedRef.current !== next.id) {
199|      loopArmedRef.current = next.id;
200|      requestPlayRef.current(next, fade);
201|    } else if (remain > fade + 1) {
202|      loopArmedRef.current = null;
203|    }
204|  }
205|
206|  function handleEnded(index: number) {
207|    const els = [firstRef.current, secondRef.current];
208|    // An element that ends while a fade is running is the one fading out.
209|    if (index !== audibleRef.current || fadeRef.current !== null) {
210|      els[index]?.pause();
211|      return;
212|    }
213|    const next = trackRef.current;
214|    if (!next) return;
215|    if (next.loop && !playlistOn) {
216|      requestPlayRef.current(next, loopFadeSec());
217|      return;
218|    }
219|    onEndedRef.current(next.id);
220|  }
221|
222|  function toggle() {
223|    const both = [firstRef.current, secondRef.current];
224|    if (!startedRef.current) {
225|      startedRef.current = true;
226|      setStarted(true);
227|      playingRef.current = true;
228|      setPlaying(true);
229|      return;
230|    }
231|    if (playingRef.current) {
232|      for (const el of both) el?.pause();
233|      playingRef.current = false;
234|      setPlaying(false);
235|      return;
236|    }
237|    playingRef.current = true;
238|    setPlaying(true);
239|    let heard = false;
240|    both.forEach((el, i) => {
241|      if (el && (levelRef.current[i] ?? 0) > 0.02) {
242|        heard = true;
243|        void el.play().catch(() => undefined);
244|      }
245|    });
246|    const next = trackRef.current;
247|    if (!heard && next) requestPlayRef.current(next, 0);
248|  }
249|
250|  function changeVolume(value: number) {
251|    setVolume(value);
252|    volumeRef.current = value;
253|    applyLevels();
254|  }
255|
256|  const credit = track ? [track.composer, track.artist].filter(Boolean).join(", ") : "";
257|  const detail = track
258|    ? [playlistOn ? null : track.emotion, soundtrackName, credit || null, track.license || null]
259|        .filter(Boolean)
260|        .join(" · ")
261|    : null;
262|
263|  return (
264|    <div className="player" role="region" aria-label="Music player" data-reduced-motion={reducedMotion}>
265|      <audio ref={firstRef} preload="auto" onTimeUpdate={(e) => handleTimeUpdate(0, e.currentTarget)} onEnded={() => handleEnded(0)} />
266|      <audio ref={secondRef} preload="auto" onTimeUpdate={(e) => handleTimeUpdate(1, e.currentTarget)} onEnded={() => handleEnded(1)} />
267|      <button type="button" onClick={toggle} aria-label={playing ? "Pause music" : "Play music"}>
268|        {playing ? "Pause" : "Play"}
269|      </button>
270|      <span className="player-track" aria-live="polite">
271|        {track ? track.title : "Music unavailable"}
272|        {detail ? ` · ${detail}` : ""}
273|        {sceneTitle ? ` · ${sceneTitle}` : ""}
274|      </span>
275|      <label className="player-volume">
276|        Volume
277|        <input
278|          type="range"
279|          min={0}
280|          max={1}
281|          step={0.05}
282|          value={volume}
283|          onChange={(e) => changeVolume(Number(e.target.value))}
284|          aria-label="Volume"
285|        />
286|      </label>
287|      <PlayerControls
288|        canNext={canSkip}
289|        onNext={onSkip}
290|        mixOn={mixOn}
291|        onToggleMix={onToggleMix}
292|        styles={styles}
293|        styleId={styleId}
294|        onStyleChange={onStyleChange}
295|        playlistLabel={playlistLabel}
296|        playlistOn={playlistOn}
297|        onTogglePlaylist={onTogglePlaylist}
298|        controlsDisabled={controlsDisabled}
299|      />
300|      {isFallback && !playlistOn ? <span className="player-note">de otra banda sonora</span> : null}
301|      {track?.attribution ? <span className="player-note">{track.attribution}</span> : null}
302|      {track?.sourceUrl ? (
303|        <a className="player-note" href={track.sourceUrl} rel="noopener noreferrer" target="_blank">
304|          Source
305|        </a>
306|      ) : null}
307|    </div>
308|  );
