21|  mixOn,
22|  onToggleMix,
23|  styles,
24|  styleId,
25|  onStyleChange,
26|  onEnded,
27|  playlistOn,
28|  playlistLabel,
29|  onTogglePlaylist,
30|  controlsDisabled,
31|}: {
