59|  trackRef.current = track;
60|  const fadeSecRef = useRef(fadeSec);
61|  fadeSecRef.current = fadeSec;
62|  const onEndedRef = useRef(onEnded);
63|  onEndedRef.current = onEnded;
64|  const playingRef = useRef(false);
65|  const startedRef = useRef(false);
66|  const firstPlayRef = useRef(true);
