155|      if (t < 1) {
156|        fadeRef.current = requestAnimationFrame(tick);
157|        return;
158|      }
159|      fadeRef.current = null;
160|      levelRef.current[srcIdx] = 0;
161|      levelRef.current[dstIdx] = 1;
162|      audibleRef.current = dstIdx;
